function isPrime(n) {
  if (typeof n !== "bigint") throw new TypeError("Use a BigInt integer");
  if (n < 2n) return false;
  for (let d = 2n; d <= n / d; d++) {
    if (n % d === 0n) return false;
  }
  return true;
}

function primeFactors(n) {
  if (typeof n !== "bigint") throw new TypeError("Use a BigInt integer");
  if (n < 1n) throw new RangeError("Use a positive integer");
  const factors = [];
  for (let d = 2n; d <= n / d; d++) {
    while (n % d === 0n) { factors.push(d); n /= d; }
  }
  if (n > 1n) factors.push(n);
  return factors;
}

function primesThrough(limit) {
  if (!Number.isSafeInteger(limit) || limit < 0 || limit > 1000000)
    throw new RangeError("Use an integer limit from 0 through 1000000");
  const composite = new Uint8Array(limit + 1);
  for (let p = 2; p * p <= limit; p++) {
    if (composite[p] === 0) {
      for (let k = p * p; k <= limit; k += p) composite[k] = 1;
    }
  }
  const primes = [];
  for (let n = 2; n <= limit; n++) {
    if (composite[n] === 0) primes.push(n);
  }
  return primes;
}

function gcd(a, b) {
  if (typeof a !== "bigint" || typeof b !== "bigint")
    throw new TypeError("Use BigInt integers");
  if (a === 0n && b === 0n) throw new RangeError("Not both zero");
  a = a < 0n ? -a : a;
  b = b < 0n ? -b : b;
  while (b !== 0n) [a, b] = [b, a % b];
  return a;
}

function extendedGcd(a, b) {
  if (typeof a !== "bigint" || typeof b !== "bigint")
    throw new TypeError("Use BigInt integers");
  if (a === 0n && b === 0n) throw new RangeError("Not both zero");
  let oldR = a < 0n ? -a : a, r = b < 0n ? -b : b;
  let oldS = 1n, s = 0n, oldT = 0n, t = 1n;
  while (r !== 0n) {
    const q = oldR / r;
    [oldR, r] = [r, oldR - q * r];
    [oldS, s] = [s, oldS - q * s];
    [oldT, t] = [t, oldT - q * t];
  }
  return { g: oldR, s: a < 0n ? -oldS : oldS,
           t: b < 0n ? -oldT : oldT };
}
